//! Durable, coalesced work for changed owner nodes. This bounds scheduler state;
//! the reference mutation graph remains resident until its separate migration.
use super::persistence::block_on_for_sync_writer;
use anyhow::{ensure,Result};
use chroma_blockstore::{provider::BlockfileProvider,arrow::provider::BlockfileReaderOptions,BlockfileWriterOptions};
use parking_lot::Mutex;
use std::{cell::RefCell,collections::{BTreeMap,VecDeque},sync::{Arc,Weak,atomic::{AtomicBool,AtomicU64,Ordering}}};
thread_local!{static CREDITS:RefCell<BTreeMap<usize,Vec<Weak<Mutex<Vec<usize>>>>>>=RefCell::new(BTreeMap::new());}
use uuid::Uuid;
pub const PAGE:usize=64;
pub const CHECK:u32=1;
pub const NEEDS_SCRUB:u32=2;
#[derive(Clone,Copy)]pub struct Limits{pub cache_pages_per_home:usize,pub max_active_pages:usize}
impl Default for Limits{fn default()->Self{Self{cache_pages_per_home:4,max_active_pages:65536}}}
#[derive(Clone,Copy,Default)]struct Slot{epoch:u64,flags:u32}
#[derive(Clone)]struct Flags{queued:bool,slots:[Slot;PAGE],dirty:bool}
impl Default for Flags{fn default()->Self{Self{queued:false,slots:[Slot::default();PAGE],dirty:false}}}
impl Flags{
 fn encode(&self)->Vec<u32>{let mut v=vec![u32::from(self.queued)];for s in self.slots{v.extend([s.epoch as u32,(s.epoch>>32) as u32,s.flags]);}v}
 fn decode(v:&[u32])->Result<Self>{ensure!(v.len()==1+3*PAGE && v[0]<=1,"work flag page extent");let mut f=Self::default();f.queued=v[0]==1;for(i,row)in v[1..].chunks_exact(3).enumerate(){ensure!(row[2]&!(CHECK|NEEDS_SCRUB)==0,"work flags");f.slots[i]=Slot{epoch:u64::from(row[0])|(u64::from(row[1])<<32),flags:row[2]};}Ok(f)}
}
#[derive(Default)]struct Home{root:Option<Uuid>,head:u64,tail:u64,active:usize,rows:usize,inflight:Option<u32>,cache:BTreeMap<u32,Flags>,order:VecDeque<u32>,tail_page:Option<(u32,Vec<u32>)>,delete_queue:Option<u32>,peak_cache:usize}
#[derive(Default)]struct Counts{marks:AtomicU64,flag_reads:AtomicU64,queue_reads:AtomicU64,commits:AtomicU64,claims:AtomicU64,claimed_rows:AtomicU64,newer_rows:AtomicU64,scheduler_reads:AtomicU64,scheduled_leaves:AtomicU64,stale_tasks:AtomicU64}
pub struct Queue{provider:BlockfileProvider,homes:Vec<Mutex<Home>>,limits:Limits,failed:AtomicBool,counts:Counts,round_robin:Mutex<usize>,admission:Mutex<Vec<usize>>}
#[derive(Debug)]pub struct Ticket{pub id:u32,pub epoch:u64,pub flags:u32}
pub struct Reservation<'a>{queue:&'a Queue,credits:Arc<Mutex<Vec<usize>>>}
impl Drop for Reservation<'_>{fn drop(&mut self){let mut reserved=self.queue.admission.lock();for(i,n)in self.credits.lock().iter().enumerate(){reserved[i]-=*n;}CREDITS.with(|v|{let mut v=v.borrow_mut();if let Some(entries)=v.get_mut(&(self.queue as *const _ as usize)){entries.retain(|w|w.as_ptr()!=Arc::as_ptr(&self.credits));if entries.is_empty(){v.remove(&(self.queue as *const _ as usize));}}});}}
#[derive(Debug)]pub struct Claim{home:usize,page:u32,pub tickets:Vec<Ticket>}
fn get(provider:&BlockfileProvider,root:Option<Uuid>,prefix:&str,key:u32)->Result<Option<Vec<u32>>>{let Some(root)=root else{return Ok(None);};block_on_for_sync_writer(async{let r=provider.read::<u32,&[u32]>(BlockfileReaderOptions::new(root,String::new())).await.map_err(|e|anyhow::anyhow!("{e}"))?;let result=r.get(prefix,key).await.map_err(|e|anyhow::anyhow!("{e}"))?.map(|v|v.to_vec());r.clear_loaded_blocks();Ok(result)})}
impl Queue{
 pub fn new(provider:BlockfileProvider,homes:usize,limits:Limits)->Result<Self>{ensure!(homes>0 && homes<=8 && limits.cache_pages_per_home>0 && limits.cache_pages_per_home<=64 && limits.max_active_pages>0,"work queue admission");Ok(Self{provider,homes:(0..homes).map(|_|Mutex::new(Home::default())).collect(),limits,failed:AtomicBool::new(false),counts:Counts::default(),round_robin:Mutex::new(0),admission:Mutex::new(vec![0;homes])})}
 pub fn reopen(provider:BlockfileProvider,roots:&[Option<Uuid>],limits:Limits)->Result<Self>{let q=Self::new(provider,roots.len(),limits)?;for(i,root)in roots.iter().enumerate(){let mut h=q.homes[i].lock();h.root=*root;if let Some(v)=get(&q.provider,*root,"control",0)?{ensure!(v.len()==11 && v[0]==0x57514f31 && v[9]<=1,"work control extent");let n=|i|u64::from(v[i])|(u64::from(v[i+1])<<32);h.head=n(1);h.tail=n(3);h.active=usize::try_from(n(5))?;h.rows=usize::try_from(n(7))?;ensure!(h.head<=h.tail && h.active<=limits.max_active_pages && h.rows<=h.active.checked_mul(PAGE).ok_or_else(||anyhow::anyhow!("work count overflow"))?,"work control bounds");if v[9]==1{q.append(&mut h,v[10])?;h.inflight=None;q.flush_home(&mut h)?;}}}Ok(q)}
 fn live(&self)->Result<()>{ensure!(!self.failed.load(Ordering::Acquire),"poisoned work queue");Ok(())}
 fn home(&self,id:u32)->usize{(id as usize/PAGE)%self.homes.len()}
 fn flush_home(&self,h:&mut Home)->Result<()>{let changed:Vec<_>=h.cache.iter().filter(|(_,v)|v.dirty).map(|(id,v)|(*id,v.encode())).collect();let tail=h.tail_page.clone();let delete=h.delete_queue;let mut control=vec![0x57514f31];for n in [h.head,h.tail,h.active as u64,h.rows as u64]{control.extend([n as u32,(n>>32)as u32]);}control.extend([u32::from(h.inflight.is_some()),h.inflight.unwrap_or(0)]);let root=h.root;
  let result=block_on_for_sync_writer(async{let mut options=BlockfileWriterOptions::new(String::new()).ordered_mutations().max_block_size_bytes(16*1024);if let Some(root)=root{options=options.fork(root);}let w=self.provider.write::<u32,Vec<u32>>(options).await.map_err(|e|anyhow::anyhow!("{e}"))?;w.set("control",0,control).await.map_err(|e|anyhow::anyhow!("{e}"))?;for(id,v)in changed{w.set("flags",id,v).await.map_err(|e|anyhow::anyhow!("{e}"))?;}if let Some(id)=delete{w.delete::<_,Vec<u32>>("queue",id).await.map_err(|e|anyhow::anyhow!("{e}"))?;}if let Some((id,v))=tail{w.set("queue",id,v).await.map_err(|e|anyhow::anyhow!("{e}"))?;}let f=w.commit::<u32,Vec<u32>>().await.map_err(|e|anyhow::anyhow!("{e}"))?;let id=f.id();f.flush::<u32,Vec<u32>>().await.map_err(|e|anyhow::anyhow!("{e}"))?;Ok::<_,anyhow::Error>(id)});
  match result{Ok(root)=>{h.root=Some(root);for v in h.cache.values_mut(){v.dirty=false;}h.tail_page=None;h.delete_queue=None;self.counts.commits.fetch_add(1,Ordering::Relaxed);Ok(())},Err(e)=>{self.failed.store(true,Ordering::Release);Err(e)}}
 }
 fn load(&self,h:&mut Home,page:u32)->Result<()>{if h.cache.contains_key(&page){h.order.retain(|v|*v!=page);h.order.push_back(page);return Ok(());}if h.cache.len()==self.limits.cache_pages_per_home{self.flush_home(h)?;let old=h.order.pop_front().unwrap();h.cache.remove(&old);}self.counts.flag_reads.fetch_add(1,Ordering::Relaxed);let value=get(&self.provider,h.root,"flags",page)?.map(|v|Flags::decode(&v)).transpose()?.unwrap_or_default();h.cache.insert(page,value);h.order.push_back(page);h.peak_cache=h.peak_cache.max(h.cache.len());Ok(())}
 fn append(&self,h:&mut Home,page:u32)->Result<()>{let segment=u32::try_from(h.tail/PAGE as u64).map_err(|_|anyhow::anyhow!("queue cursor exhausted"))?;if h.tail_page.as_ref().is_some_and(|(id,_)|*id!=segment){self.flush_home(h)?;}if h.tail_page.is_none(){self.counts.queue_reads.fetch_add(1,Ordering::Relaxed);h.tail_page=Some((segment,get(&self.provider,h.root,"queue",segment)?.unwrap_or_default()));}let v=&mut h.tail_page.as_mut().unwrap().1;ensure!(v.len()==(h.tail%PAGE as u64)as usize && v.len()<PAGE,"queue segment extent");v.push(page);h.tail=h.tail.checked_add(1).ok_or_else(||anyhow::anyhow!("queue tail exhausted"))?;Ok(())}
 /// Call before changing authority. Repeated changes only update one bounded
 /// cached flag page; a full cache flushes durably before eviction.
 pub fn mark(&self,id:u32,flags:u32)->Result<()>{self.live()?;ensure!(flags>0 && flags&!(CHECK|NEEDS_SCRUB)==0,"work event flags");let home=self.home(id);let mut reserved=self.admission.lock();let mut h=self.homes[home].lock();let page=id/PAGE as u32;self.load(&mut h,page)?;let queued=h.cache[&page].queued;if !queued{let credit=CREDITS.with(|v|v.borrow().get(&(self as *const _ as usize)).is_some_and(|entries|entries.iter().rev().any(|w|w.upgrade().is_some_and(|credits|{let mut credits=credits.lock();if credits[home]>0{credits[home]-=1;true}else{false}}))));if credit{reserved[home]-=1;}else{ensure!(h.active.checked_add(reserved[home]).is_some_and(|n|n<self.limits.max_active_pages),"work queue capacity before mutation");}self.append(&mut h,page)?;h.active+=1;h.cache.get_mut(&page).unwrap().queued=true;}let prior=h.cache[&page].slots[id as usize%PAGE];let epoch=prior.epoch.checked_add(1).ok_or_else(||anyhow::anyhow!("work epoch exhausted"))?;if prior.flags==0{h.rows+=1;}let page=h.cache.get_mut(&page).unwrap();page.slots[id as usize%PAGE]=Slot{epoch,flags:prior.flags|flags};page.dirty=true;self.counts.marks.fetch_add(1,Ordering::Relaxed);Ok(())}
 /// Held credits prevent another worker from consuming structural headroom.
 pub fn reserve(&self,pages:usize)->Result<Reservation<'_>>{self.live()?;let mut reserved=self.admission.lock();for(i,home)in self.homes.iter().enumerate(){ensure!(home.lock().active.checked_add(reserved[i]).and_then(|n|n.checked_add(pages)).is_some_and(|n|n<=self.limits.max_active_pages),"work page headroom before structural detach");}for n in reserved.iter_mut(){*n+=pages;}let credits=Arc::new(Mutex::new(vec![pages;self.homes.len()]));CREDITS.with(|v|v.borrow_mut().entry(self as *const _ as usize).or_default().push(Arc::downgrade(&credits)));Ok(Reservation{queue:self,credits})}
 pub fn flush(&self)->Result<Vec<Option<Uuid>>>{self.live()?;let mut roots=Vec::new();for home in &self.homes{let mut h=home.lock();self.flush_home(&mut h)?;roots.push(h.root);}Ok(roots)}
 pub fn claim(&self)->Result<Option<Claim>>{self.live()?;let mut cursor=self.round_robin.lock();ensure!(self.homes.iter().all(|h|h.lock().inflight.is_none()),"only one claimed page globally");for offset in 0..self.homes.len(){let home=(*cursor+offset)%self.homes.len();let mut h=self.homes[home].lock();if h.head==h.tail{continue;}ensure!(h.inflight.is_none(),"only one claimed flag page per home");let segment=u32::try_from(h.head/PAGE as u64).map_err(|_|anyhow::anyhow!("queue head exhausted"))?;let values=if h.tail_page.as_ref().is_some_and(|(id,_)|*id==segment){h.tail_page.as_ref().unwrap().1.clone()}else{self.counts.queue_reads.fetch_add(1,Ordering::Relaxed);get(&self.provider,h.root,"queue",segment)?.ok_or_else(||anyhow::anyhow!("queue segment missing"))?};ensure!(values.len()<=PAGE,"queue segment bound");let page=*values.get((h.head%PAGE as u64)as usize).ok_or_else(||anyhow::anyhow!("queue head missing"))?;self.load(&mut h,page)?;ensure!(h.cache[&page].queued,"uncoalesced queue ticket");let tickets=h.cache[&page].slots.iter().enumerate().filter(|(_,v)|v.flags!=0).map(|(slot,v)|Ticket{id:page*PAGE as u32+slot as u32,epoch:v.epoch,flags:v.flags}).collect::<Vec<_>>();h.head+=1;if h.head%PAGE as u64==0{h.delete_queue=Some(segment);}h.inflight=Some(page);self.flush_home(&mut h)?;*cursor=(home+1)%self.homes.len();self.counts.claims.fetch_add(1,Ordering::Relaxed);self.counts.claimed_rows.fetch_add(tickets.len()as u64,Ordering::Relaxed);return Ok(Some(Claim{home,page,tickets}));}Ok(None)}
 pub fn ack(&self,claim:Claim,still_work:&[bool])->Result<()>{self.live()?;ensure!(still_work.len()==claim.tickets.len(),"work ack extent");let _admission=self.admission.lock();let mut h=self.homes[claim.home].lock();ensure!(h.inflight==Some(claim.page),"work ack identity");self.load(&mut h,claim.page)?;let mut cleared=0;for(t,again)in claim.tickets.iter().zip(still_work){let slot=&mut h.cache.get_mut(&claim.page).unwrap().slots[t.id as usize%PAGE];if slot.epoch==t.epoch && !again{slot.flags=0;cleared+=1;}else{if slot.epoch!=t.epoch{self.counts.newer_rows.fetch_add(1,Ordering::Relaxed);}slot.flags|=CHECK;}}h.rows-=cleared;let remains=h.cache[&claim.page].slots.iter().any(|v|v.flags!=0);if remains{self.append(&mut h,claim.page)?;}else{h.cache.get_mut(&claim.page).unwrap().queued=false;h.active-=1;}h.cache.get_mut(&claim.page).unwrap().dirty=true;h.inflight=None;self.flush_home(&mut h)}
 pub fn pending(&self)->usize{self.homes.iter().map(|h|h.lock().rows).sum()}
 pub fn queued_pages(&self)->usize{self.homes.iter().map(|h|h.lock().active).sum()}
 pub fn scheduler_read(&self){self.counts.scheduler_reads.fetch_add(1,Ordering::Relaxed);}
 pub fn scheduled(&self,count:usize){self.counts.scheduled_leaves.fetch_add(count as u64,Ordering::Relaxed);}
 pub fn stale(&self){self.counts.stale_tasks.fetch_add(1,Ordering::Relaxed);}
 pub fn report(&self)->serde_json::Value{serde_json::json!({"policy":"dirty-owner-work-pages-v1","scheduler_node_point_reads":self.counts.scheduler_reads.load(Ordering::Relaxed),"scheduled_leaf_jobs":self.counts.scheduled_leaves.load(Ordering::Relaxed),"stale_jobs":self.counts.stale_tasks.load(Ordering::Relaxed),"max_claimed_jobs":64,"pending_candidates":self.pending(),"active_pages":self.queued_pages(),"cache_page_cap_per_home":self.limits.cache_pages_per_home,"max_active_pages_per_home":self.limits.max_active_pages,"cache_pages":self.homes.iter().map(|h|h.lock().cache.len()).sum::<usize>(),"peak_cache_pages_per_home":self.homes.iter().map(|h|h.lock().peak_cache).max().unwrap_or(0),"flag_page_reads":self.counts.flag_reads.load(Ordering::Relaxed),"queue_page_reads":self.counts.queue_reads.load(Ordering::Relaxed),"commits":self.counts.commits.load(Ordering::Relaxed),"mark_calls":self.counts.marks.load(Ordering::Relaxed),"claimed_pages":self.counts.claims.load(Ordering::Relaxed),"claimed_rows":self.counts.claimed_rows.load(Ordering::Relaxed),"newer_rows_retained":self.counts.newer_rows.load(Ordering::Relaxed),"poisoned":self.failed.load(Ordering::Relaxed),"scope":"Fixed home roots/cursors, bounded flag cache and <=64 claimed node jobs per page. Flag state and queue segments live in blockstore; provider indexes/encoded buffers are separate. Resident mutation graph is not removed by this slice."})}
}
#[cfg(test)]mod tests{
 use super::*;use chroma_blockstore::arrow::provider::ArrowBlockfileProvider;use chroma_cache::new_cache_for_test;use chroma_storage::{local::LocalStorage,Storage};
 fn provider(path:&std::path::Path)->BlockfileProvider{BlockfileProvider::ArrowBlockfileProvider(ArrowBlockfileProvider::new(Storage::Local(LocalStorage::new(path.to_str().unwrap())),16*1024,new_cache_for_test(),new_cache_for_test(),2))}
 #[tokio::test(flavor="multi_thread",worker_threads=2)]async fn owner_work_queue_durable_coalescing_claim_newer_and_capacity(){let dir=tempfile::tempdir().unwrap();let q=Queue::new(provider(dir.path()),2,Limits{cache_pages_per_home:1,max_active_pages:2}).unwrap();q.mark(1,CHECK).unwrap();q.mark(1,NEEDS_SCRUB).unwrap();q.mark(2,CHECK).unwrap();q.mark(128,CHECK).unwrap();assert_eq!(q.pending(),3);assert_eq!(q.queued_pages(),2);q.flush().unwrap();assert!(q.mark(256,CHECK).is_err(),"capacity rejects new page before caller mutation");let c=q.claim().unwrap().unwrap();assert_eq!(c.tickets.iter().map(|v|v.id).collect::<Vec<_>>(),vec![1,2]);assert_eq!(c.tickets[0].flags,CHECK|NEEDS_SCRUB);q.mark(1,NEEDS_SCRUB).unwrap();q.mark(3,CHECK).unwrap();q.ack(c,&[false,false]).unwrap();assert_eq!(q.pending(),3);let c=q.claim().unwrap().unwrap();assert_eq!(c.tickets[0].id,128);q.ack(c,&[false]).unwrap();let c=q.claim().unwrap().unwrap();assert_eq!(c.tickets.iter().map(|v|v.id).collect::<Vec<_>>(),vec![1,3]);q.ack(c,&[false,false]).unwrap();assert_eq!(q.pending(),0);assert!(q.claim().unwrap().is_none());let roots=q.flush().unwrap();let reopened=Queue::reopen(q.provider.clone(),&roots,q.limits).unwrap();assert_eq!(reopened.pending(),0);let report=q.report();assert_eq!(report["newer_rows_retained"],1);assert!(report["peak_cache_pages_per_home"].as_u64().unwrap()<=1);println!("WORK_QUEUE_CORE {report}");}
 #[tokio::test(flavor="multi_thread",worker_threads=2)]async fn owner_work_queue_claim_reopen_and_reserved_headroom(){let dir=tempfile::tempdir().unwrap();let p=provider(dir.path());let q=Queue::new(p.clone(),1,Limits{cache_pages_per_home:1,max_active_pages:2}).unwrap();q.mark(1,CHECK).unwrap();{let _held=q.reserve(1).unwrap();std::thread::scope(|scope|{assert!(scope.spawn(||q.mark(128,CHECK)).join().unwrap().is_err());});q.mark(64,CHECK).unwrap();}let claim=q.claim().unwrap().unwrap();q.mark(1,NEEDS_SCRUB).unwrap();let roots=q.flush().unwrap();drop(claim);let restored=Queue::reopen(p,&roots,q.limits).unwrap();let c=restored.claim().unwrap().unwrap();restored.ack(c,&[false]).unwrap();let c=restored.claim().unwrap().unwrap();assert_eq!(c.tickets[0].id,1);assert_eq!(c.tickets[0].flags,CHECK|NEEDS_SCRUB);restored.ack(c,&[false]).unwrap();assert_eq!(restored.pending(),0);println!("WORK_QUEUE_RECOVER bounded in-flight page is requeued with newer flags; held credits reject competing new page");}

}
